--liquibase formatted sql
--changeset catalogimport:001
create table catalog_source (id bigint generated by default as identity primary key, code varchar(80) not null, name varchar(200) not null, created_at timestamp with time zone not null, constraint uk_source_code unique(code));
create table import_definition (id bigint generated by default as identity primary key, source_id bigint not null references catalog_source(id), version integer not null, library_code varchar(80) not null, supplier_column varchar(100) not null, reference_column varchar(100) not null, group_column varchar(100) not null, price_column varchar(100) not null, created_at timestamp with time zone not null, constraint uk_definition_version unique(source_id,version));
create table import_batch (id bigint generated by default as identity primary key, definition_id bigint not null references import_definition(id), content_hash varchar(64) not null, original_file_name varchar(255) not null, original_content bytea not null, status varchar(20) not null, received_at timestamp with time zone not null, record_count bigint not null default 0, issue_count bigint not null default 0, constraint uk_batch_idempotency unique(definition_id,content_hash));
create table candidate_offer (id bigint generated by default as identity primary key, batch_id bigint not null references import_batch(id), supplier_code varchar(80) not null, supplier_reference varchar(160) not null, group_code varchar(80) not null, price numeric(19,6) not null, source_line integer not null, constraint uk_candidate_identity unique(batch_id,supplier_code,supplier_reference));
create table import_mutation (id bigint generated by default as identity primary key, batch_id bigint not null references import_batch(id), candidate_id bigint not null references candidate_offer(id), type varchar(20) not null, previous_price numeric(19,6), constraint uk_mutation_candidate unique(candidate_id));
create table library_offer (id bigint generated by default as identity primary key, library_code varchar(80) not null, supplier_code varchar(80) not null, supplier_reference varchar(160) not null, group_code varchar(80) not null, price numeric(19,6) not null, active boolean not null, updated_at timestamp with time zone not null, constraint uk_library_offer_identity unique(library_code,supplier_code,supplier_reference));
